[
  {
    "id": "vul_py_62_1",
    "patch": "async def massban(
    self,
    ctx: commands.Context,
    user_ids: commands.Greedy[RawUserIds],
    days: Optional[int] = None,
    *,
    reason: str = None,
):
    """Mass bans user(s) from the server.

    User IDs need to be provided in order to ban
    using this command."""
    banned = []
    errors = {}
    upgrades = []

    async def show_results():
        text = _("Banned {num} users from the server.").format(
            num=humanize_number(len(banned))
        )
        if errors:
            text += _("\nErrors:\n")
            text += "\n".join(errors.values())
        if upgrades:
            text += _(\
                "\nFollowing user IDs have been upgraded from a temporary to a permanent ban:\n"
            )
            text += humanize_list(upgrades)

        for p in pagify(text):
            await ctx.send(p)

    def remove_processed(ids):
        return [_id for _id in ids if _id not in banned and _id not in errors]

    user_ids = list(set(user_ids))  # No dupes

    author = ctx.author
    guild = ctx.guild

    if not user_ids:
        await ctx.send_help()
        return

    if days is None:
        days = await self.config.guild(guild).default_days()

    if not (0 <= days <= 7):
        await ctx.send(_("Invalid days. Must be between 0 and 7."))
        return

    if not guild.me.guild_permissions.ban_members:
        return await ctx.send(_("I lack the permissions to do this."))

    tempbans = await self.config.guild(guild).current_tempbans()

    ban_list = await guild.bans()
    for entry in ban_list:
        for user_id in user_ids:
            if entry.user.id == user_id:
                if user_id in tempbans:
                    # We need to check if a user is tempbanned here because otherwise they won't be processed later on.
                    continue
                else:
                    errors[user_id] = _("User with ID {user_id} is already banned.").format(
                        user_id=user_id
                    )

    user_ids = remove_processed(user_ids)

    if not user_ids:
        await show_results()
        return

    for user_id in user_ids:
        user = guild.get_member(user_id)
        if user is not None:
            # --- Begin hierarchy checks ---
            if user == guild.owner:
                errors[user_id] = _("Cannot ban the server owner (ID: {user_id}).").format(user_id=user_id)
                continue
            if author.top_role <= user.top_role and author != guild.owner:
                errors[user_id] = _("You do not have permission to ban user {user_id} due to role hierarchy.").format(user_id=user_id)
                continue
            if guild.me.top_role <= user.top_role:
                errors[user_id] = _("I do not have permission to ban user {user_id} due to role hierarchy.").format(user_id=user_id)
                continue
            # --- End hierarchy checks ---
            if user_id in tempbans:
                # We need to check if a user is tempbanned here because otherwise they won't be processed later on.
                continue
            else:
                # Instead of replicating all that handling... gets attr from decorator
                try:
                    success, reason = await self.ban_user(
                        user=user, ctx=ctx, days=days, reason=reason, create_modlog_case=True
                    )
                    if success:
                        banned.append(user_id)
                    else:
                        errors[user_id] = _("Failed to ban user {user_id}: {reason}").format(
                            user_id=user_id, reason=reason
                        )
                except Exception as e:
                    errors[user_id] = _("Failed to ban user {user_id}: {reason}").format(
                        user_id=user_id, reason=e
                    )

    user_ids = remove_processed(user_ids)

    if not user_ids:
        await show_results()
        return

    for user_id in user_ids:
        user = guild.get_member(user_id)
        if user is not None:
            # Already handled above, skip
            continue
        # For hackbans (users not in guild), we cannot check their roles, but we can prevent banning the owner
        if user_id == guild.owner_id:
            errors[user_id] = _("Cannot ban the server owner (ID: {user_id}).").format(user_id=user_id)
            continue
        # Optionally, you could add a check to prevent banning users with IDs matching the bot or author
        user_obj = discord.Object(id=user_id)
        audit_reason = get_audit_reason(author, reason)
        queue_entry = (guild.id, user_id)
        async with self.config.guild(guild).current_tempbans() as tempbans:
            if user_id in tempbans:
                tempbans.remove(user_id)
                upgrades.append(str(user_id))
                log.info(
                    "{}({}) upgraded the tempban for {} to a permaban.".format(
                        author.name, author.id, user_id
                    )
                )
                banned.append(user_id)
            else:
                try:
                    await guild.ban(user_obj, reason=audit_reason, delete_message_days=days)
                    log.info("{}({}) hackbanned {}".format(author.name, author.id, user_id))
                except discord.NotFound:
                    errors[user_id] = _("User with ID {user_id} not found").format(
                        user_id=user_id
                    )
                    continue
                except discord.Forbidden:
                    errors[user_id] = _(
                        "Could not ban user with ID {user_id}: missing permissions."
                    ).format(user_id=user_id)
                    continue
                else:
                    banned.append(user_id)

        await modlog.create_case(
            self.bot,
            guild,
            ctx.message.created_at.replace(tzinfo=timezone.utc),
            "hackban",
            user_id,
            author,
            reason,
            until=None,
            channel=None,
        )
    await show_results()
"
  }
]
